cuda_source = """
#include <cuda_fp16.h>

__global__ void matmul_kernel(const half* A, const half* B, half* C, int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < M && col < N) {
        float sum = 0.0f;
        for (int k = 0; k < K; ++k) {
            sum += __half2float(A[row * K + k]) * __half2float(B[k * N + col]);
        }
        C[row * N + col] = __float2half(sum);
    }
}

void launch_matmul(const at::Tensor& A, const at::Tensor& B, at::Tensor& C) {
    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(1);

    const dim3 block_size(16, 16);
    const dim3 grid_size((N + block_size.x - 1) / block_size.x, 
                         (M + block_size.y - 1) / block_size.y);

    matmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<half>(),
        B.data_ptr<half>(),
        C.data_ptr<half>(),
        M, N, K
    );
}
"""

